import logging


class Bts(object):
    """ Represents common BTS API. """

    _CONNECTION_LOG_MSG = 'Connecting to {} with address: {}, port: {}, username: {}, password: {}'
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        self._api = None
        self._logger = logging.getLogger()
        self._host = None

    def connect_to(self, config, name, log_dir, timeout, **kwargs):
        """
        Opens connection to BTS using appropriate API.
        :param config: BTS configuration object containing all required connection data
        :type config: taf.config.testline.gnb.gnb.gNB or taf.config.testline.enb.RealEnb
        :param name: connection alias which will be used during creation of BTS connection
        :type name: str
        :param log_dir: path to directory where additional logs will be stored
        :type log_dir: str
        :param timeout: time (in seconds) to wait for successful connection
        :type timeout: int
        :param kwargs: additional connection parameters, i.e. cu_id=0, du_id=0
        """
        self._connect_to(config=config,
                         name=name,
                         log_dir=log_dir,
                         timeout=timeout,
                         **kwargs)

    def get_active_alarms(self, connection, timeout):
        """
        Gets currently active alarms from BTS.
        :param connection: connection alias provided during creation of BTS connection
        :type connection: str
        :param timeout: time to wait for BTS response with requested active alarms
        :type timeout: float or int
        :return: details of active alarms returned by BTS API
        :rtype: list(dict)
        """
        return self._get_active_alarms(connection=connection, timeout=timeout)

    def disconnect(self, connection):
        """
        Closes connection to BTS.
        :param connection: connection alias provided during creation of BTS connection
        :type connection: str
        """
        self._disconnect(connection=connection)

    def _connect_to(self, config, name, log_dir, timeout, **kwargs):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._connect_to.__name__))

    def _get_active_alarms(self, connection, timeout):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._get_active_alarms.__name__))

    def _disconnect(self, connection):
        raise NotImplementedError(self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                                                 self._disconnect.__name__))

    @property
    def host(self):
        return self._host
